/* Generated by 'inkamath --compile' from heat.ink: edit that, not this.
 * The arithmetic is in the order the definitions give it, so do not build it
 * with -ffast-math, which reorders. A compiler may also fuse a multiply and an
 * add, rounding once where the definitions round twice (-ffp-contract): often
 * closer to exact, but the step then depends on how it is built, so build
 * what 'inkamath --check' writes the way the step itself is built. */
#ifndef HEAT_H
#define HEAT_H

#include <math.h>
#include <string.h>

/* Using it:
 *
 *     heat m;
 *     heat_init(&m);
 *     heat_step(&m, q);  once for each index, the first 0
 *     m.u[0][i][j]  is then u_n, row i+1 and column j+1
 *
 * A step takes q_n, the input at its index. After a step, m.name[k] is
 * name_(n-k) for each sequence: q and u (k <= 1). The parameters are fields
 * holding the file's values once heat_init has run: dt = 0.01. After assigning
 * one, call heat_update. Compiled in as constants, these cannot change: N. A
 * term the interpreter would refuse is NaN, and so is every term that reads
 * one, through a guard or a comparison as through arithmetic. Built with
 * -ffinite-math-only, which -ffast-math implies, GCC removes the tests that
 * make it so, and Clang warns of each NaN.
 */

/* The parameters, which the host may assign, then what derives from them,
 * then the index of the latest step and each sequence's terms from that
 * index back. */
typedef struct heat {
    double dt;
    double A[3][3];
    long long index_;
    double q[1];
    double u[2][3][1];
} heat;

/* The inverse of a 3x3 matrix, in place, as the interpreter takes it: Gauss-Jordan
 * on the largest pivot, and NaN in every cell where there is none. */
static inline void heat_inverse3_(double a_[3][3]) {
    double r_[3][3];
    for (int i_ = 0; i_ < 3; ++i_)
        for (int j_ = 0; j_ < 3; ++j_) r_[i_][j_] = i_ == j_ ? 1.0 : 0.0;
    for (int col_ = 0; col_ < 3; ++col_) {
        int pivot_ = col_;
        for (int row_ = col_ + 1; row_ < 3; ++row_)
            if (fabs(a_[row_][col_]) > fabs(a_[pivot_][col_]) ||
                (a_[pivot_][col_] == 0.0 && a_[row_][col_] != 0.0))
                pivot_ = row_;
        if (a_[pivot_][col_] == 0.0) {
            for (int i_ = 0; i_ < 3; ++i_)
                for (int j_ = 0; j_ < 3; ++j_) a_[i_][j_] = NAN;
            return;
        }
        for (int j_ = 0; j_ < 3; ++j_) {
            const double s_ = a_[pivot_][j_], t_ = r_[pivot_][j_];
            a_[pivot_][j_] = a_[col_][j_];
            r_[pivot_][j_] = r_[col_][j_];
            a_[col_][j_]   = s_;
            r_[col_][j_]   = t_;
        }
        const double scale_ = a_[col_][col_];
        for (int j_ = 0; j_ < 3; ++j_) {
            a_[col_][j_] = a_[col_][j_] / scale_;
            r_[col_][j_] = r_[col_][j_] / scale_;
        }
        for (int row_ = 0; row_ < 3; ++row_) {
            const double factor_ = a_[row_][col_];
            if (row_ == col_ || factor_ == 0.0) continue;
            for (int j_ = 0; j_ < 3; ++j_) {
                a_[row_][j_] = a_[row_][j_] - factor_ * a_[col_][j_];
                r_[row_][j_] = r_[row_][j_] - factor_ * r_[col_][j_];
            }
        }
    }
    memcpy(a_, r_, sizeof r_);
}

/* Computes what derives from the parameters: call it after assigning one. */
static inline void heat_update(heat* m_) {
    const double t4_ = 0.0 + m_->dt * -4.0;
    double t0_[3][3] = {{0.25 + m_->dt * 8.0, t4_, 0.0 + m_->dt * 0.0}, {t4_, 0.25 + m_->dt * 8.0, t4_}, {0.0 + m_->dt * 0.0, t4_, 0.25 + m_->dt * 8.0}};
    heat_inverse3_(t0_);
    m_->A[0][0] = t0_[0][0] * 0.25;
    m_->A[0][1] = t0_[0][1] * 0.25;
    m_->A[0][2] = t0_[0][2] * 0.25;
    m_->A[1][0] = t0_[1][0] * 0.25;
    m_->A[1][1] = t0_[1][1] * 0.25;
    m_->A[1][2] = t0_[1][2] * 0.25;
    m_->A[2][0] = t0_[2][0] * 0.25;
    m_->A[2][1] = t0_[2][1] * 0.25;
    m_->A[2][2] = t0_[2][2] * 0.25;
}

static inline void heat_init(heat* m_) {
    memset(m_, 0, sizeof *m_);
    m_->dt = 0.01;
    m_->index_ = -1;
    heat_update(m_);
}

/* Advances to the next index, the first at 0, and computes its terms. */
static inline void heat_step(heat* m_, double q_in_) {
    ++m_->index_;
    memcpy(m_->u[1], m_->u[0], sizeof m_->u[1]);
    m_->q[0] = q_in_;
    const double t1_ = m_->u[1][0][0] + m_->dt * 1.0 * m_->q[0];
    const double t2_ = m_->u[1][1][0] + m_->dt * 0.0 * m_->q[0];
    const double t3_ = m_->u[1][2][0] + m_->dt * 0.0 * m_->q[0];
    m_->u[0][0][0] = m_->index_ == 0 ? 0.0 : m_->A[0][0] * t1_ + m_->A[0][1] * t2_ + m_->A[0][2] * t3_;
    m_->u[0][1][0] = m_->index_ == 0 ? 0.0 : m_->A[1][0] * t1_ + m_->A[1][1] * t2_ + m_->A[1][2] * t3_;
    m_->u[0][2][0] = m_->index_ == 0 ? 0.0 : m_->A[2][0] * t1_ + m_->A[2][1] * t2_ + m_->A[2][2] * t3_;
    if (isnan(m_->u[0][0][0]) || isnan(m_->u[0][1][0]) || isnan(m_->u[0][2][0]))
        for (int i_ = 0; i_ < 3; ++i_)
            for (int j_ = 0; j_ < 1; ++j_) m_->u[0][i_][j_] = NAN;
}

#endif
